"""Saved routes API (spec 005): bearer-auth CRUD over the routes repository.

Every endpoint resolves ``holder_id`` from the ``Authorization: Bearer`` token
via ``auth.hash_token`` + the repositories layer, so a holder can only ever
see and mutate their own saved routes (AC-1, AC-2, AC-6).
"""

from __future__ import annotations

import uuid
from collections.abc import Callable
from typing import Any

from fastapi import APIRouter, Depends, Header, HTTPException, status
from pydantic import BaseModel

from app.auth import hash_token
from app.db import get_connection
from app.repositories import routes as routes_repo

router = APIRouter(prefix="/saved-routes", tags=["saved-routes"])

_UNAUTHORIZED = HTTPException(
    status_code=status.HTTP_401_UNAUTHORIZED,
    detail="Missing or invalid bearer token",
    headers={"WWW-Authenticate": "Bearer"},
)

# Candidate resolver names on the prefs repository, tried in order.
_TOKEN_RESOLVERS: tuple[str, ...] = (
    "get_holder_id_by_token_hash",
    "holder_id_for_token_hash",
    "resolve_holder_id",
    "get_holder_id",
)

_LOOKUP_SQL = "SELECT holder_id FROM tokens WHERE token_hash = %s"


def _lookup_holder_id(token_hash: str) -> str | None:
    """Resolve holder_id for a token hash via repositories, else direct lookup."""
    for name in _TOKEN_RESOLVERS:
        candidate: Callable[[str], Any] | None = getattr(
            routes_repo, name, None
        ) or getattr(_prefs_repo(), name, None)
        if candidate is not None:
            holder_id = candidate(token_hash)
            return str(holder_id) if holder_id else None
    with get_connection() as conn, conn.cursor() as cur:
        cur.execute(_LOOKUP_SQL, (token_hash,))
        row = cur.fetchone()
    return str(row[0]) if row else None


def _prefs_repo() -> Any:
    from app.repositories import prefs

    return prefs


def bearer_holder(
    authorization: str | None = Header(default=None),
) -> str:
    """FastAPI dependency: bearer token -> holder_id (401 when invalid)."""
    if not authorization or not authorization.lower().startswith("bearer "):
        raise _UNAUTHORIZED
    token = authorization.split(" ", 1)[1].strip()
    if not token:
        raise _UNAUTHORIZED
    holder_id = _lookup_holder_id(hash_token(token))
    if not holder_id:
        raise _UNAUTHORIZED
    return holder_id


class SavedRoutePayload(BaseModel):
    request: dict[str, Any]
    response: dict[str, Any]


@router.post("", status_code=status.HTTP_201_CREATED)
def save_route(
    payload: SavedRoutePayload,
    holder_id: str = Depends(bearer_holder),
) -> dict[str, Any]:
    """Save (upsert) a route for the authenticated holder."""
    route_id = str(uuid.uuid4())
    return routes_repo.save_route(
        holder_id, route_id, payload.request, payload.response
    )


@router.get("")
def list_saved_routes(
    holder_id: str = Depends(bearer_holder),
) -> list[dict[str, Any]]:
    """List the authenticated holder's saved routes only."""
    return routes_repo.list_routes(holder_id)


class PrefsPayload(BaseModel):
    default_preference: dict[str, Any] | None = None


@router.get("/prefs")
def get_saved_route_prefs(
    holder_id: str = Depends(bearer_holder),
) -> dict[str, Any]:
    """Return the authenticated holder's saved preferences (AC-6)."""
    prefs = _prefs_repo().get_prefs(holder_id)
    if prefs is None:
        return {"holder_id": holder_id, "default_preference": None}
    return prefs


@router.put("/prefs")
def update_saved_route_prefs(
    payload: PrefsPayload,
    holder_id: str = Depends(bearer_holder),
) -> dict[str, Any]:
    """Upsert the authenticated holder's saved preferences (AC-6)."""
    return _prefs_repo().update_prefs(holder_id, payload.model_dump())


@router.get("/{route_id}")
def recall_saved_route(
    route_id: str,
    holder_id: str = Depends(bearer_holder),
) -> dict[str, Any]:
    """Recall one saved route; 404 when missing or owned by another holder."""
    route = routes_repo.recall_route(holder_id, route_id)
    if route is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Saved route not found"
        )
    return route


@router.delete("/{route_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_saved_route(
    route_id: str,
    holder_id: str = Depends(bearer_holder),
) -> None:
    """Delete one saved route; 404 when missing or owned by another holder."""
    if not routes_repo.delete_route(holder_id, route_id):
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Saved route not found"
        )

"""API tests for saved routes (spec 005, AC-1/AC-2/AC-6).

The bearer-token -> holder_id resolution is monkeypatched so tests are
hermetic (no DATABASE_URL), and the routes repository is replaced with an
in-memory fake that records save/list/recall/delete calls per holder.
"""

from __future__ import annotations

from collections.abc import Iterator
from typing import Any

import pytest
from fastapi.testclient import TestClient

from app import saved_routes
from app.auth import hash_token
from app.main import app as fastapi_app

_HOLDER_A = "holder-a"
_HOLDER_B = "holder-b"
_TOKEN_A = "token-a"
_TOKEN_B = "token-b"

_REQUEST: dict[str, Any] = {"origin": [52.52, 13.405], "destination": [48.135, 11.582]}
_RESPONSE: dict[str, Any] = {"distance_km": 585.0, "duration_h": 6.0}


class _FakeRoutesRepo:
    """In-memory stand-in for app.repositories.routes."""

    def __init__(self) -> None:
        self._rows: dict[tuple[str, str], dict[str, Any]] = {}

    def save_route(
        self, holder_id: str, route_id: str, request: Any, response: Any
    ) -> dict[str, Any]:
        row = {
            "id": route_id,
            "holder_id": holder_id,
            "request": request,
            "response": response,
        }
        self._rows[(holder_id, route_id)] = row
        return row

    def list_routes(self, holder_id: str) -> list[dict[str, Any]]:
        return [
            row for (holder, _), row in self._rows.items() if holder == holder_id
        ]

    def recall_route(self, holder_id: str, route_id: str) -> dict[str, Any] | None:
        return self._rows.get((holder_id, route_id))

    def delete_route(self, holder_id: str, route_id: str) -> bool:
        return self._rows.pop((holder_id, route_id), None) is not None


@pytest.fixture()
def fake_repo() -> _FakeRoutesRepo:
    return _FakeRoutesRepo()


@pytest.fixture()
def client(
    fake_repo: _FakeRoutesRepo, monkeypatch: pytest.MonkeyPatch
) -> Iterator[TestClient]:
    """TestClient with auth and repository monkeypatched to fakes."""

    def fake_lookup(token_hash: str) -> str | None:
        if token_hash == hash_token(_TOKEN_A):
            return _HOLDER_A
        if token_hash == hash_token(_TOKEN_B):
            return _HOLDER_B
        return None

    monkeypatch.setattr(saved_routes, "_lookup_holder_id", fake_lookup)
    monkeypatch.setattr(saved_routes, "routes_repo", fake_repo)
    with TestClient(fastapi_app) as test_client:
        yield test_client


def _auth(token: str) -> dict[str, str]:
    return {"Authorization": f"Bearer {token}"}


def _save(client: TestClient, token: str = _TOKEN_A) -> Any:
    return client.post(
        "/saved-routes",
        json={"request": _REQUEST, "response": _RESPONSE},
        headers=_auth(token),
    )


def test_save_route_returns_201_for_bearer_holder(client: TestClient) -> None:
    response = _save(client)

    assert response.status_code == 201
    body = response.json()
    assert body["holder_id"] == _HOLDER_A
    assert body["request"] == _REQUEST
    assert body["response"] == _RESPONSE
    assert body["id"]


def test_list_returns_only_own_saved_routes(client: TestClient) -> None:
    mine = _save(client).json()
    _save(client, token=_TOKEN_B)

    response = client.get("/saved-routes", headers=_auth(_TOKEN_A))

    assert response.status_code == 200
    ids = [row["id"] for row in response.json()]
    assert ids == [mine["id"]]


def test_recall_saved_route_returns_saved_payload(client: TestClient) -> None:
    saved = _save(client).json()

    response = client.get(f"/saved-routes/{saved['id']}", headers=_auth(_TOKEN_A))

    assert response.status_code == 200
    body = response.json()
    assert body["id"] == saved["id"]
    assert body["request"] == _REQUEST
    assert body["response"] == _RESPONSE


def test_recall_unknown_route_is_404(client: TestClient) -> None:
    response = client.get("/saved-routes/nope", headers=_auth(_TOKEN_A))

    assert response.status_code == 404


def test_recall_other_holders_route_is_404_and_leaks_no_token(
    client: TestClient, caplog: pytest.LogCaptureFixture
) -> None:
    """AC-6: cross-holder recall is 404 and no bearer token is leaked."""
    saved = _save(client, token=_TOKEN_B).json()

    with caplog.at_level("DEBUG"):
        response = client.get(f"/saved-routes/{saved['id']}", headers=_auth(_TOKEN_A))

    assert response.status_code == 404
    assert _TOKEN_A not in response.text
    assert _TOKEN_B not in response.text
    assert _TOKEN_A not in str(response.request.url)
    assert _TOKEN_B not in str(response.request.url)
    assert _TOKEN_A not in caplog.text
    assert _TOKEN_B not in caplog.text


def test_delete_saved_route_removes_it(client: TestClient) -> None:
    saved = _save(client).json()

    deleted = client.delete(f"/saved-routes/{saved['id']}", headers=_auth(_TOKEN_A))
    recalled = client.get(f"/saved-routes/{saved['id']}", headers=_auth(_TOKEN_A))

    assert deleted.status_code == 204
    assert recalled.status_code == 404


def test_missing_bearer_token_is_401(client: TestClient) -> None:
    response = client.get("/saved-routes")

    assert response.status_code == 401
